CREATE TABLE IF NOT EXISTS stations (id SERIAL PRIMARY KEY, station_code VARCHAR(32) UNIQUE NOT NULL, location TEXT NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, status VARCHAR(32) DEFAULT 'Normal', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS weather_readings (id BIGSERIAL PRIMARY KEY, station_id INTEGER REFERENCES stations(id), timestamp TIMESTAMPTZ NOT NULL, temperature DOUBLE PRECISION, pressure DOUBLE PRECISION, humidity DOUBLE PRECISION, source VARCHAR(32) DEFAULT 'simulated');
CREATE TABLE IF NOT EXISTS anomalies (id BIGSERIAL PRIMARY KEY, station_id INTEGER REFERENCES stations(id), timestamp TIMESTAMPTZ NOT NULL, anomaly_score DOUBLE PRECISION, anomaly_type VARCHAR(64), severity VARCHAR(16), explanation TEXT, prototype_inference BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS alerts (id BIGSERIAL PRIMARY KEY, anomaly_id BIGINT REFERENCES anomalies(id), alert_code VARCHAR(32), severity VARCHAR(16), reason TEXT, recommended_action TEXT, status VARCHAR(24) DEFAULT 'OPEN', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sensor_health (id BIGSERIAL PRIMARY KEY, station_id INTEGER REFERENCES stations(id), timestamp TIMESTAMPTZ DEFAULT NOW(), score DOUBLE PRECISION, anomaly_frequency DOUBLE PRECISION, drift_score DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS simulation_events (id BIGSERIAL PRIMARY KEY, scenario VARCHAR(64), started_at TIMESTAMPTZ DEFAULT NOW(), payload JSONB);
